/**
 * Shared foundation types used across AGRC-OS frontend services.
 * These provide common patterns for API responses and entity shapes.
 */

export interface BaseEntityDto {
  id: string;
  createdAt?: string;
  updatedAt?: string;
}

export interface PaginatedResponse<T> {
  items: T[];
  total: number;
  page?: number;
  limit?: number;
}

export interface MessageResponse {
  message: string;
  success?: boolean;
}

/**
 * Flexible indexed record type used throughout the GRC platform.
 * Replaces inline `any` annotations across all component files,
 * centralizing dynamic-data typing into a single named interface.
 *
 * @deprecated
 * @removal-date Phase 6 (Frontend consumption)
 * @owner DOS
 * @replacement DAuth frontend services (core/dauth/) Prefer specific interfaces when the shape is known.
 * Use GrcRecord only when the structure is genuinely dynamic
 * or comes from an untyped source (AI inference, telemetry).
 * Will be removed once all consumers are migrated to specific DTOs.
 */
/* eslint-disable @typescript-eslint/no-explicit-any */
export interface GrcRecord {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}
/* eslint-enable @typescript-eslint/no-explicit-any */

import { Component, inject, signal, ChangeDetectionStrategy} from '@angular/core';
import { CommonModule } from '@angular/common';
import { AppDatePipe } from '@app/shared/pipes/app-date.pipe';
import { FormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { I18nService } from '@app/core/services/ui-infra/i18n.service';
import { TrialExtensionApiService } from '../../core/subscription/trial-extension.api.service';
import { GrcRecord } from '@app/core/models/shared.types';

@Component({
    changeDetection: ChangeDetectionStrategy.OnPush,
    selector: 'app-trial-extension-admin-page',
    imports: [CommonModule, AppDatePipe, FormsModule],
    template: `
    <div class="p-6 max-w-4xl space-y-6">
      <div>
        <h1 class="text-2xl font-semibold">{{ i18n.translate('admin.trialExtensionRequests') }}</h1>
        <p class="text-sm text-gray-500">{{ i18n.translate('admin.reviewAndManageTrialExtensionRequests') }}</p>
      </div>

      <button class="border rounded px-4 py-2" (click)="load()" [disabled]="loading()">
        {{ i18n.translate('admin.refresh') }}
      </button>

      <div class="border rounded-2xl bg-white p-4 overflow-auto">
        <table aria-label="Trial Extension Requests table" class="min-w-full text-sm">
          <thead>
            <tr class="text-left border-b">
              <th class="py-2 pr-4">{{ i18n.translate('admin.created') }}</th>
              <th class="py-2 pr-4">{{ i18n.translate('admin.tenant') }}</th>
              <th class="py-2 pr-4">{{ i18n.translate('admin.days') }}</th>
              <th class="py-2 pr-4">{{ i18n.translate('admin.reason') }}</th>
              <th class="py-2 pr-4">{{ i18n.translate('admin.status') }}</th>
              <th class="py-2 pr-4">{{ i18n.translate('admin.actions') }}</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let r of requests()" class="border-b">
              <td class="py-2 pr-4">{{ r.created_at | appDate:'short' }}</td>
              <td class="py-2 pr-4">{{ r.tenant_id }}</td>
              <td class="py-2 pr-4">{{ r.requested_days }}</td>
              <td class="py-2 pr-4 max-w-xs truncate">{{ r.reason }}</td>
              <td class="py-2 pr-4">
                <span [class]="statusClass(r.status)">{{ r.status }}</span>
              </td>
              <td class="py-2 pr-4">
                <div *ngIf="r.status === 'pending'" class="flex gap-2">
                  <button class="rounded px-3 py-1 bg-green-600 text-white text-xs"
                    (click)="approve(r.request_id)">{{ i18n.translate('admin.approve') }}</button>
                  <button class="rounded px-3 py-1 bg-red-600 text-white text-xs"
                    (click)="reject(r.request_id)">{{ i18n.translate('admin.reject') }}</button>
                </div>
                <span *ngIf="r.status !== 'pending'" class="text-xs text-gray-400">
                  {{ r.decision_notes || '—' }}
                </span>
              </td>
            </tr>
          </tbody>
        </table>

        <div *ngIf="!requests().length" class="text-sm text-gray-400 py-4 text-center">
          {{ i18n.translate('admin.noExtensionRequestsFound') }}
        </div>
      </div>
    </div>
  `
})
export class TrialExtensionAdminPageComponent {
  private api = inject(TrialExtensionApiService);
  readonly i18n = inject(I18nService);
  readonly loading = signal(false);
  readonly requests = signal<GrcRecord[]>([]);

  async load() {
    this.loading.set(true);
    try {
      const res = await firstValueFrom(this.api.getStatus());
      this.requests.set(res?.requests ?? []);
    } finally {
      this.loading.set(false);
    }
  }

  async approve(requestId: string) {
    await firstValueFrom(this.api.approve(requestId, 'Approved via admin panel'));
    await this.load();
  }

  async reject(requestId: string) {
    await firstValueFrom(this.api.reject(requestId, 'Rejected via admin panel'));
    await this.load();
  }

  statusClass(status: string): string {
    if (status === 'approved') return 'text-green-600 font-semibold';
    if (status === 'rejected') return 'text-red-600 font-semibold';
    return 'text-amber-600 font-semibold';
  }

  ngOnInit() {
    this.load();
  }

}

import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  inject,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

import { DialogModule } from 'primeng/dialog';
import { InputTextarea } from 'primeng/inputtextarea';
import { ButtonModule } from 'primeng/button';

import { I18nService } from '@app/core/services/ui-infra/i18n.service';

// ── Component ─────────────────────────────────────────────────────────────────

/**
 * Dialog for rejecting an AI audit recommendation with a reason.
 * Re-used as the "create dialog" concept from the audit page (the only
 * user-initiated dialog is the reject-with-reason flow).
 */
@Component({
    selector: 'app-ai-audit-create-dialog',
    imports: [
        CommonModule,
        FormsModule,
        DialogModule,
        InputTextarea,
        ButtonModule,
    ],
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `
    <p-dialog
      [header]="i18n.translate('ai.audit.rejectReason')"
      [visible]="visible"
      (visibleChange)="close.emit()"
      [modal]="true"
      [style]="{ width: '450px' }"
      [dismissableMask]="true">

      <div class="reject-form">
        <label>{{ i18n.translate('ai.audit.reason') }}</label>
        <textarea
          pInputTextarea
          [(ngModel)]="reason"
          [rows]="4"
          class="w-full mt-2">
        </textarea>
      </div>

      <ng-template pTemplate="footer">
        <button
          pButton
          [label]="i18n.translate('ai.audit.cancel')"
          class="p-button-text"
          (click)="close.emit()">
        </button>
        <button
          pButton
          [label]="i18n.translate('ai.audit.confirmReject')"
          class="p-button-danger"
          [loading]="saving"
          (click)="saved.emit(reason)">
        </button>
      </ng-template>
    </p-dialog>
  `,
    styles: [`
    .reject-form label { font-weight: 600; }
    .w-full { width: 100%; }
    .mt-2 { margin-top: 0.5rem; }
  `]
})
export class AiAuditCreateDialogComponent {
  readonly i18n = inject(I18nService);

  /** Whether the dialog is visible. */
  @Input() visible = false;

  /** Whether a save/reject operation is in progress. */
  @Input() saving = false;

  /** Emitted when the dialog should close. */
  @Output() close = new EventEmitter<void>();

  /** Emitted when the user confirms the rejection with a reason string. */
  @Output() saved = new EventEmitter<string>();

  /** The rejection reason text. */
  reason = '';
}

import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  inject,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

import { DialogModule } from 'primeng/dialog';
import { TagModule } from 'primeng/tag';
import { ButtonModule } from 'primeng/button';
import { InputTextarea } from 'primeng/inputtextarea';

import { I18nService } from '@app/core/services/ui-infra/i18n.service';

// ── Component ─────────────────────────────────────────────────────────────────

@Component({
    selector: 'app-ai-hitl-approval-dialog',
    imports: [
        CommonModule,
        FormsModule,
        DialogModule,
        TagModule,
        ButtonModule,
        InputTextarea,
    ],
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `
    <p-dialog
      [header]="i18n.translate('ai.hitl.reviewDialogTitle')"
      [visible]="visible"
      (visibleChange)="close.emit()"
      [modal]="true"
      [style]="{width: '480px'}"
      [closable]="true">

      <div class="review-form" style="margin-top:12px;">
        <div class="detail-field">
          <label class="detail-label">{{ i18n.translate('ai.hitl.decision') }}</label>
          <p-tag [value]="decision" [severity]="decisionSeverity(decision)" />
        </div>
        <div class="detail-field">
          <label class="detail-label">{{ i18n.translate('ai.hitl.notes') }}</label>
          <textarea
            pInputTextarea
            [(ngModel)]="notes"
            [rows]="3"
            class="w-full"
            [placeholder]="i18n.translate('ai.hitl.notesPlaceholder')">
          </textarea>
        </div>
      </div>

      <ng-template pTemplate="footer">
        <button
          pButton
          [label]="i18n.translate('common.cancel')"
          icon="pi pi-times"
          class="p-button-text"
          (click)="close.emit()">
        </button>
        <button
          pButton
          [label]="i18n.translate('ai.hitl.submitReview')"
          icon="pi pi-check"
          [loading]="loading"
          (click)="saved.emit(notes)">
        </button>
      </ng-template>
    </p-dialog>
  `,
    styles: [`
    .review-form { display:flex; flex-direction:column; gap:12px; }
    .detail-field { display:flex; flex-direction:column; gap:2px; }
    .detail-label { font-size:var(--font-size-xs); font-weight:700; text-transform:uppercase; letter-spacing:.4px; color:var(--text-muted); }
    .w-full { width:100%; }
  `]
})
export class AiHitlApprovalDialogComponent {
  readonly i18n = inject(I18nService);

  /** Whether the dialog is visible. */
  @Input() visible = false;

  /** The pre-selected decision (approved/rejected/escalated). */
  @Input() decision = '';

  /** Whether the submit action is loading. */
  @Input() loading = false;

  /** Emitted when the dialog should close. */
  @Output() close = new EventEmitter<void>();

  /** Emitted when the user submits with notes. */
  @Output() saved = new EventEmitter<string>();

  /** Notes text bound to the textarea. */
  notes = '';

  /** Map decision to PrimeNG tag severity. */
  decisionSeverity(d: string): 'success' | 'warning' | 'danger' | 'info' {
    switch (d) {
      case 'approved': return 'success';
      case 'rejected': return 'danger';
      case 'escalated': return 'warning';
      default: return 'info';
    }
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  inject,
} from '@angular/core';
import { CommonModule } from '@angular/common';

import { DialogModule } from 'primeng/dialog';
import { TagModule } from 'primeng/tag';
import { ProgressSpinnerModule } from 'primeng/progressspinner';

import { I18nService } from '@app/core/services/ui-infra/i18n.service';
import { GrcRecord } from '@app/core/models/shared.types';

// ── Interfaces ────────────────────────────────────────────────────────────────

export interface AiSignalDetail {
  id: string;
  signal_type: string;
  severity: string;
  status: string;
  source_module: string;
  detected_at: string;
  events?: GrcRecord[];
  issues?: GrcRecord[];
}

// ── Component ─────────────────────────────────────────────────────────────────

@Component({
    selector: 'app-ai-audit-detail-drawer',
    imports: [
        CommonModule,
        DialogModule,
        TagModule,
        ProgressSpinnerModule,
    ],
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `
    <p-dialog
      [header]="i18n.translate('ai.audit.signalDetail')"
      [visible]="visible"
      (visibleChange)="close.emit()"
      position="right"
      [modal]="true"
      [style]="{ width: '700px' }"
      [dismissableMask]="true">

      <div *ngIf="loading" class="dialog-spinner">
        <p-progressSpinner strokeWidth="3" />
      </div>

      <div *ngIf="!loading && detail">
        <h4>{{ detail.signal_type }}</h4>
        <p>
          <strong>{{ i18n.translate('ai.audit.severity') }}:</strong>
          <p-tag [value]="detail.severity" [severity]="getSeverityTag(detail.severity)" class="ms-2" />
        </p>
        <p>
          <strong>{{ i18n.translate('ai.audit.status') }}:</strong>
          <p-tag [value]="detail.status" [severity]="getStatusTag(detail.status)" class="ms-2" />
        </p>

        <!-- Events -->
        <div *ngIf="detail.events?.length" class="detail-section">
          <h5>{{ i18n.translate('ai.audit.events') }}</h5>
          <ul class="detail-list">
            <li *ngFor="let evt of detail.events">
              <span class="mono">{{ evt.event_type || evt.type || 'event' }}</span>
              -- {{ evt.description || evt.message || (evt | json) }}
            </li>
          </ul>
        </div>

        <!-- Linked Issues -->
        <div *ngIf="detail.issues?.length" class="detail-section">
          <h5>{{ i18n.translate('ai.audit.linkedIssues') }}</h5>
          <ul class="detail-list">
            <li *ngFor="let iss of detail.issues">
              <p-tag [value]="iss.severity" [severity]="getSeverityTag(iss.severity)" class="me-2" />
              {{ iss.issue_type || iss.type }}: {{ iss.description || '--' }}
            </li>
          </ul>
        </div>
      </div>
    </p-dialog>
  `,
    styles: [`
    .dialog-spinner { display: flex; justify-content: center; padding: 2rem; }
    .ms-2 { margin-inline-start: 0.5rem; }
    .me-2 { margin-inline-end: 0.5rem; }
    .mono { font-family: 'Fira Code', 'Consolas', monospace; font-size: var(--font-size-tag); }
    .detail-section { margin-top: 1rem; }
    .detail-section h5 { margin: 0 0 0.5rem; font-weight: 600; }
    .detail-list { list-style: disc; padding-inline-start: 1.25rem; margin: 0; }
    .detail-list li { margin-bottom: 0.35rem; line-height: 1.4; }
  `]
})
export class AiAuditDetailDrawerComponent {
  readonly i18n = inject(I18nService);

  /** Whether the drawer is visible. */
  @Input() visible = false;

  /** Whether detail data is loading. */
  @Input() loading = false;

  /** The signal detail data to display. */
  @Input() detail: AiSignalDetail | null = null;

  /** Emitted when the drawer is closed. */
  @Output() close = new EventEmitter<void>();

  /** Map severity level to PrimeNG tag severity. */
  getSeverityTag(severity: string): 'success' | 'info' | 'warning' | 'danger' | undefined {
    switch (severity) {
      case 'critical': case 'high': return 'danger';
      case 'medium': return 'warning';
      case 'low': return 'info';
      case 'info': return 'success';
      default: return undefined;
    }
  }

  /** Map status to PrimeNG tag severity. */
  getStatusTag(status: string): 'success' | 'info' | 'warning' | 'danger' | undefined {
    switch (status) {
      case 'resolved': case 'accepted': return 'success';
      case 'open': case 'pending': return 'warning';
      case 'dismissed': case 'rejected': return 'danger';
      default: return 'info';
    }
  }
}

