    const apiMap: Record<string, () => ReturnType<typeof this.api.getCoverageReport>> = {
      coverage: () => this.api.getCoverageReport(),
      aging: () => this.api.getAgingReport(),
      orphan: () => this.api.getOrphanReport(),
