          </p-table>
        </div>

        <!-- Actions -->
        <div class="fd-actions">
          <p-button [label]="L.launchGap" icon="pi pi-chart-bar" styleClass="p-button-sm" (onClick)="launchGap.emit(fw.frameworkId)" />
          <p-button [label]="L.runAssessment" icon="pi pi-play" styleClass="p-button-outlined p-button-sm" (onClick)="assess.emit(fw.frameworkId)" />
          <p-button [label]="L.exportReport" icon="pi pi-download" styleClass="p-button-text p-button-sm" (onClick)="exportFw.emit(fw.frameworkId)" />
