        <div class="gd-actions">
          <p-button [label]="L.startRemediation" icon="pi pi-wrench" styleClass="p-button-sm" (onClick)="startRem.emit(detail.gap.gapId)" />
          <p-button [label]="L.attachEvidence" icon="pi pi-paperclip" styleClass="p-button-outlined p-button-sm" (onClick)="attachEv.emit(detail.gap.gapId)" />
          <p-button [label]="L.markReady" icon="pi pi-check" styleClass="p-button-outlined p-button-sm" (onClick)="validate.emit(detail.gap.gapId)" />
          <p-button [label]="L.closeGap" icon="pi pi-times" styleClass="p-button-text p-button-sm" (onClick)="closeGap.emit(detail.gap.gapId)" />
          <p-button [label]="L.acceptRisk" icon="pi pi-shield" styleClass="p-button-text p-button-sm p-button-danger" (onClick)="acceptRisk.emit(detail.gap.gapId)" />
        </div>
      </div>
