      .peer-split { grid-template-columns: 1fr; }
      .peer-divider { width: 100%; height: 1px; margin: 0 8px; }
    }
  `]
})
export class RiskPeerDialogueComponent {
  public i18n = inject(I18nService);

  /** Dialog visibility */
  @Input() visible = false;

  /** Localized labels bag */
  @Input() labels: Record<string, string> = {};

  /** Active peer review data (agent side) */
  @Input() activePeerReview: Record<string, any> | null = null;

  /** Human assessment form */
  @Input() form: PeerReviewFormData = { riskId: '', reviewId: '', humanLikelihood: 3, humanImpact: 3, humanControlEff: 50, humanReasoning: '' };

  /** Whether there is a disagreement between agent and human scores */
  @Input() hasDisagreement = false;

  /** Dialogue thread entries */
  @Input() dialogueEntries: PeerDialogueEntry[] = [];

  /** New dialogue message text (two-way bound internally) */
  newDialogueMessage = '';

  /** Scale options (1-5) */
  scaleOptions = [1, 2, 3, 4, 5].map(v => ({ label: String(v), value: v }));

  /** Emitted when dialog is closed */
  @Output() close = new EventEmitter<void>();

  /** Emitted when human score is submitted */
  @Output() submitHuman = new EventEmitter<PeerReviewFormData>();

  /** Emitted when review is finalized */
  @Output() finalize = new EventEmitter<void>();

  /** Emitted when a dialogue message is sent */
  @Output() sendDialogue = new EventEmitter<string>();

  /** Score CSS class helpers */
  scoreClass(score: number): string { return score >= 20 ? 'score-high' : score >= 12 ? 'score-medium' : 'score-low'; }
  likelihoodClass(v: number): string { return v >= 4 ? 'score-high' : v >= 2 ? 'score-medium' : 'score-low'; }
  impactClass(v: number): string { return v >= 4 ? 'score-high' : v >= 2 ? 'score-medium' : 'score-low'; }
}

import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { I18nService } from '@app/core/services/ui-infra/i18n.service';
import { DialogModule } from 'primeng/dialog';
import { InputTextModule } from 'primeng/inputtext';
import { InputTextarea } from 'primeng/inputtextarea';
import { DropdownModule } from 'primeng/dropdown';
import { SliderModule } from 'primeng/slider';
import { ButtonModule } from 'primeng/button';

/** Form model for risk create/edit */
export interface RiskFormData {
  title: string;
  description: string;
  category: string;
  likelihood: number;
  impact: number;
  owner: string;
  ownerTeamId: string;
  status: string;
  controlEffectiveness: number;
  nextReviewDate: string;
  threatContext: string;
  businessImpact: string;
}

/**
 * Presentational component: Create/Edit risk dialog with full form
 * including title, description, category, owner, team, likelihood/impact
 * sliders, status lifecycle dropdown, and supplementary fields.
 */
@Component({
    changeDetection: ChangeDetectionStrategy.OnPush,
    selector: 'app-risk-register-create-dialog',
    imports: [CommonModule, FormsModule, DialogModule, InputTextModule, InputTextarea, DropdownModule, SliderModule, ButtonModule],
    template: `
    <p-dialog [header]="editMode ? labels.editRisk : labels.createRisk" [(visible)]="visible" [modal]="true" [focusTrap]="true" [style]="{width:'600px'}" (onHide)="close.emit()">
      <div class="dialog-form">
        <div class="field">
          <label for="risk-title">{{ labels.title }}</label>
          <input id="risk-title" pInputText [(ngModel)]="form.title" class="w-full" />
        </div>
        <div class="field">
          <label for="risk-desc">{{ labels.description }}</label>
          <textarea id="risk-desc" pInputTextarea [(ngModel)]="form.description" [rows]="3" class="w-full"></textarea>
        </div>
        <div class="field-row">
          <div class="field">
            <label>{{ labels.category }}</label>
            <p-dropdown [(ngModel)]="form.category" [options]="categoryOptions" optionLabel="label" optionValue="value" styleClass="w-full" appendTo="body" />
          </div>
          <div class="field">
            <label>{{ labels.owner }}</label>
            <p-dropdown [options]="userOptions" optionLabel="fullName" optionValue="userId"
                        [(ngModel)]="form.owner" [placeholder]="isAr ? selectOwnerLabelAr : selectOwnerLabelEn" [filter]="true" filterBy="fullName,email"
                        [showClear]="true" styleClass="w-full" appendTo="body">
              <ng-template let-user pTemplate="item">
                <div>
                  <span>{{ user.fullName }}</span>
                  <small class="text-muted" style="margin-inline-start:8px">{{ user.departmentName || '' }}</small>
                </div>
              </ng-template>
            </p-dropdown>
          </div>
        </div>
        <div class="field">
          <label>{{ responsibleTeamLabel }}</label>
          <p-dropdown [options]="teamOptions" optionLabel="name" optionValue="teamId"
                      [(ngModel)]="form.ownerTeamId" [placeholder]="isAr ? selectTeamLabelAr : selectTeamLabelEn" [filter]="true" [showClear]="true"
                      styleClass="w-full" appendTo="body" />
        </div>
        <div class="field-row">
          <div class="field">
            <label>{{ labels.likelihood }}: {{ form.likelihood }}</label>
            <p-slider [(ngModel)]="form.likelihood" [min]="1" [max]="5" [step]="1" />
          </div>
          <div class="field">
            <label>{{ labels.impact }}: {{ form.impact }}</label>
            <p-slider [(ngModel)]="form.impact" [min]="1" [max]="5" [step]="1" />
          </div>
        </div>
        <div class="field">
          <label>{{ labels.status }}</label>
          <p-dropdown [(ngModel)]="form.status"
                      [options]="statusOptions"
                      optionLabel="label" optionValue="value" styleClass="w-full" appendTo="body"
                      [disabled]="editMode && statusOptions.length === 0" />
        </div>
        <div class="field-row">
          <div class="field">
            <label>{{ labels.controlEff }} (0\u2013100%)</label>
            <input pInputText type="number" [(ngModel)]="form.controlEffectiveness" class="w-full" min="0" max="100" />
          </div>
          <div class="field">
            <label>{{ labels.nextReviewDate }}</label>
            <input pInputText type="date" [(ngModel)]="form.nextReviewDate" class="w-full" />
          </div>
        </div>
        <div class="field">
          <label>{{ labels.businessImpact }}</label>
          <input pInputText [(ngModel)]="form.businessImpact" class="w-full" />
        </div>
        <div class="field">
          <label>{{ labels.threatContext }}</label>
          <input pInputText [(ngModel)]="form.threatContext" class="w-full" />
        </div>
      </div>
      <ng-template pTemplate="footer">
        <p-button [label]="labels.cancel" icon="pi pi-times" severity="secondary" [text]="true" (onClick)="close.emit()" />
        <p-button [label]="labels.save" icon="pi pi-check" (onClick)="saved.emit(form)" [disabled]="!form.title.trim()" />
      </ng-template>
    </p-dialog>
  `,
    styles: [`
    .dialog-form { display: flex; flex-direction: column; gap: var(--space-md, 12px); }
    .field { display: flex; flex-direction: column; gap: var(--space-xs, 4px); }
    .field label { font-size: var(--font-size-sm); font-weight: 500; color: var(--text-muted); }
    .field-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-md, 12px); }
    .w-full { width: 100%; }
    .text-muted { color: var(--text-muted); }
  `]
})
export class RiskRegisterCreateDialogComponent {
  public i18n = inject(I18nService);

  /** Dialog visibility */
  @Input() visible = false;

  /** Whether this is edit mode */
