export class WorkflowBuilderComponent implements OnInit, OnDestroy {
    private apiclientSvc = inject(ApiClientService);
  workflows: WorkflowDefinition[] = [];
  loading = true;
  errorMsg = '';
  showDialog = false;
  showSimResult = false;
  simResult: Record<string, any> | null = null;

  editingWorkflow: WorkflowDefinition | null = null;
  formName = '';
  formDescription = '';
  formTrigger = '';
  formTriggerConditions: string[] = [''];
  formSteps: WorkflowStep[] = [{ trigger: '', action: '', condition: '', notification: '' }];

  triggerTypes = [
    { label: 'Manual', value: 'manual' }, { label: 'Schedule', value: 'schedule' },
    { label: 'Event', value: 'event' }, { label: 'Approval', value: 'approval' },
  ];

  canvasMode = false;
  activeWorkflow: WorkflowDefinition | null = null;
  canvasNodes: WorkflowNode[] = [];
  canvasEdges: WorkflowEdge[] = [];
  canvasWidth = 1200;
  canvasHeight = 600;
  validationErrors: string[] = [];

  showNodeConfig = false;
  configNode: WorkflowNode | null = null;
  selectedNodeId: string | null = null;

  nodeTypes = buildNodeTypesFromPackage();

  private cdr = inject(ChangeDetectorRef);

  constructor(public i18n: I18nService, private operationsSvc: GrcOperationsService) {}

  readonly headerActions = computed<PageHeaderAction[]>(() => {
    if (this.canvasMode) {
      return [{ id: 'back-to-list', labelEn: this.i18n.translate('Back to List'), labelAr: this.i18n.translate('Back to List'), icon: 'chevron-left', primary: false }];
    }
    return [
      { id: 'from-template', labelEn: this.i18n.translate('From Template'), labelAr: this.i18n.translate('From Template'), icon: 'copy', primary: false },
      { id: 'new-workflow', labelEn: this.i18n.translate('New Workflow'), labelAr: this.i18n.translate('New Workflow'), icon: 'create', primary: true },
    ];
  });

  onHeaderAction(actionId: string): void {
    switch (actionId) {
      case 'back-to-list': this.exitCanvas(); break;
      case 'from-template': this.loadTemplates(); break;
      case 'new-workflow': this.openCreateDialog(); break;
    }
  }

  ngOnInit(): void { this.loadWorkflows(); }
  ngOnDestroy(): void { /* cleanup handled by child canvas component */ }

  loadWorkflows(): void {
    this.loading = true; this.errorMsg = '';
    this.operationsSvc.getWorkflows().subscribe({
      next: (res: Record<string, any>) => { this.workflows = res.workflows || res || []; this.loading = false; this.cdr.markForCheck(); },
      error: () => { this.errorMsg = this.i18n.translate('Failed to load workflows. Please try again.'); this.loading = false; this.cdr.markForCheck(); },
    });
  }

  openCreateDialog(): void {
    this.editingWorkflow = null; this.formName = ''; this.formDescription = ''; this.formTrigger = '';
    this.formTriggerConditions = ['']; this.formSteps = [{ trigger: '', action: '', condition: '', notification: '' }];
    this.showDialog = true;
  }

  openEditDialog(wf: WorkflowDefinition): void {
    this.editingWorkflow = wf; this.formName = wf.name || ''; this.formDescription = wf.description || '';
    this.formTrigger = wf.trigger_type || wf.trigger || '';
    this.formTriggerConditions = wf.definition?.triggerConditions?.length ? [...wf.definition.triggerConditions] : [''];
    this.formSteps = wf.definition?.steps?.length ? wf.definition.steps.map(s => ({ ...s })) : [{ trigger: '', action: '', condition: '', notification: '' }];
    this.showDialog = true;
  }

  closeDialog(): void { this.showDialog = false; this.editingWorkflow = null; }
  addStep(): void { this.formSteps.push({ trigger: '', action: '', condition: '', notification: '' }); }

  saveWorkflow(): void {
    const payload = { name: this.formName, description: this.formDescription, trigger_type: this.formTrigger,
      definition: { steps: this.formSteps.filter(s => s.action), triggerConditions: this.formTriggerConditions.filter(c => c.trim()) } };
    if (this.editingWorkflow) {
      const id = this.editingWorkflow.workflow_id || this.editingWorkflow.id;
      this.apiclientSvc.put(`/workflows/${id}`, payload).subscribe({
        next: (updated: Record<string, any>) => { const idx = this.workflows.findIndex(w => (w.workflow_id || w.id) === id); if (idx >= 0) this.workflows[idx] = { ...this.workflows[idx], ...updated, ...payload, updated_at: new Date().toISOString() }; this.workflows = [...this.workflows]; this.closeDialog(); },
        error: () => { const idx = this.workflows.findIndex(w => (w.workflow_id || w.id) === id); if (idx >= 0) this.workflows[idx] = { ...this.workflows[idx], ...payload, updated_at: new Date().toISOString() }; this.workflows = [...this.workflows]; this.closeDialog(); },
      });
    } else {
      this.operationsSvc.createWorkflow(payload).subscribe({ next: (wf: Record<string, any>) => { this.workflows = [wf as WorkflowDefinition, ...this.workflows]; this.closeDialog(); } });
    }
  }

  simulate(wf: WorkflowDefinition): void {
    const id = wf.workflow_id || wf.id;
    this.apiclientSvc.post(`/workflows/${id}/simulate`, {}).subscribe({
      next: (res: Record<string, any>) => { this.simResult = res; this.showSimResult = true; },
      error: (err: any) => { this.simResult = { error: err?.error?.error || 'Simulation failed' }; this.showSimResult = true; },
    });
  }

  loadTemplates(): void {
    this.operationsSvc.getWorkflowTemplates().subscribe({
      next: (res: Record<string, any>) => {
        const templates = res.templates || res || [];
        if (templates.length > 0) {
          this.formName = templates[0].name + ' (copy)'; this.formDescription = templates[0].description || '';
          this.formSteps = templates[0].definition?.steps || [{ trigger: '', action: '', condition: '', notification: '' }];
          this.formTriggerConditions = templates[0].definition?.triggerConditions || ['']; this.editingWorkflow = null; this.showDialog = true;
        }
      },
    });
  }

  // -- Canvas orchestration --

  openCanvas(wf: WorkflowDefinition): void {
    this.activeWorkflow = wf; this.canvasMode = true; this.selectedNodeId = null;
    if (wf.canvas) { this.canvasNodes = wf.canvas.nodes.map(n => ({ ...n, config: { ...n.config } })); this.canvasEdges = wf.canvas.edges.map(e => ({ ...e })); }
    else { this.canvasNodes = []; this.canvasEdges = []; }
    this.runValidation();
  }

  exitCanvas(): void { this.canvasMode = false; this.activeWorkflow = null; this.canvasNodes = []; this.canvasEdges = []; }

  onNodesChange(nodes: WorkflowNode[]): void { this.canvasNodes = nodes; this.runValidation(); }
  onEdgesChange(edges: WorkflowEdge[]): void { this.canvasEdges = edges; }

  onConfigureNode(node: WorkflowNode): void { this.configNode = { ...node, config: { ...node.config } }; this.showNodeConfig = true; }

  deleteNode(nodeId: string): void {
    this.canvasNodes = this.canvasNodes.filter(n => n.nodeId !== nodeId);
    this.canvasEdges = this.canvasEdges.filter(e => e.sourceNodeId !== nodeId && e.targetNodeId !== nodeId);
    if (this.selectedNodeId === nodeId) this.selectedNodeId = null;
    this.runValidation();
  }

  closeNodeConfig(node: WorkflowNode | null): void {
    if (node) { const idx = this.canvasNodes.findIndex(n => n.nodeId === node.nodeId); if (idx >= 0) { this.canvasNodes[idx] = { ...node }; this.canvasNodes = [...this.canvasNodes]; } }
    this.showNodeConfig = false; this.configNode = null; this.runValidation();
  }

  private runValidation(): void { this.validationErrors = validateWorkflowGraph(this.canvasNodes).errors; }

  saveCanvas(): void {
    if (!this.activeWorkflow) return;
    const id = this.activeWorkflow.workflow_id || this.activeWorkflow.id;
    const canvasData: WorkflowCanvas = { workflowId: id || uid(), nodes: this.canvasNodes.map(n => ({ ...n, config: { ...n.config } })), edges: this.canvasEdges.map(e => ({ ...e })) };
    const payload = { ...this.activeWorkflow, canvas: serializeCanvas(canvasData), updated_at: new Date().toISOString() };
    this.apiclientSvc.put(`/workflows/${id}`, payload).subscribe({
      next: (updated: Record<string, any>) => { const idx = this.workflows.findIndex(w => (w.workflow_id || w.id) === id); if (idx >= 0) { this.workflows[idx] = { ...this.workflows[idx], ...updated, canvas: canvasData, updated_at: new Date().toISOString() }; this.workflows = [...this.workflows]; } this.activeWorkflow = { ...this.activeWorkflow!, canvas: canvasData }; },
      error: () => { const idx = this.workflows.findIndex(w => (w.workflow_id || w.id) === id); if (idx >= 0) { this.workflows[idx] = { ...this.workflows[idx], canvas: canvasData, updated_at: new Date().toISOString() }; this.workflows = [...this.workflows]; } this.activeWorkflow = { ...this.activeWorkflow!, canvas: canvasData }; },
    });
  }
}

