/**
 * Canonical ECharts Component
 * 
 * This is the primary chart wrapper for ECharts visualizations.
 * ECharts is the default chart engine for all standard charts (bar, line, pie, donut, radar, gauge, heatmap, etc.).
 * 
 * @see CHART_POLICY.md for chart library usage policy
 * 
 * Usage:
 * ```typescript
 * <app-echart [options]="chartOptions" [height]="'360px'" [theme]="'light'" />
 * ```
 */
import {
  Component, Input, ElementRef, ViewChild, OnInit, OnChanges,
  AfterViewInit, OnDestroy, SimpleChanges, NgZone, ChangeDetectionStrategy} from '@angular/core';
import { CommonModule } from '@angular/common';
import type { EChartsType } from 'echarts';

@Component({
    changeDetection: ChangeDetectionStrategy.OnPush,
    selector: 'app-echart',
    imports: [CommonModule],
    template: `<div #chartEl class="echart-container" [style.height]="height" [style.width]="width"></div>`,
    styles: [`.echart-container { width: 100%; min-height: 200px; }`]
})
export class EChartComponent implements OnInit, AfterViewInit, OnChanges, OnDestroy {
  @ViewChild('chartEl', { static: true }) chartEl!: ElementRef<HTMLDivElement>;
  @Input() options: Record<string, unknown> = {};
  @Input() height = '360px';
  @Input() width = '100%';
  @Input() theme: 'light' | 'dark' | string = 'light';

  private chart: EChartsType | null = null;
  private resizeObserver?: ResizeObserver;

  constructor(private zone: NgZone) {}

  ngOnInit(): void {}

  ngAfterViewInit(): void {
    this.zone.runOutsideAngular(async () => {
      const echarts = await import('echarts');
      this.chart = echarts.init(this.chartEl.nativeElement, this.theme === 'dark' ? 'dark' : undefined);
      const safeOptions = this.options && typeof this.options === 'object' ? this.options : {};
      this.chart.setOption(safeOptions, { notMerge: true, lazyUpdate: true });
      this.resizeObserver = new ResizeObserver(() => {
        if (this.chart && this.chartEl?.nativeElement?.offsetParent != null) this.chart.resize();
      });
      this.resizeObserver.observe(this.chartEl.nativeElement);
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.chart && (changes['options'] || changes['theme'])) {
      this.zone.runOutsideAngular(() => {
        const safeOptions = this.options && typeof this.options === 'object' ? this.options : {};
        this.chart!.setOption(safeOptions, { notMerge: true, lazyUpdate: true });
      });
    }
  }

  ngOnDestroy(): void {
    this.resizeObserver?.disconnect();
    this.chart?.dispose();
    this.chart = null;
  }
}

