import { Component, Input, inject, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { ButtonModule } from 'primeng/button';
import { MenuModule } from 'primeng/menu';
import { MenuItem } from 'primeng/api';
import { ToastService } from '@app/core/dos/shell/toast.service';

@Component({
    changeDetection: ChangeDetectionStrategy.OnPush,
    selector: 'app-export-button',
    imports: [CommonModule, ButtonModule, MenuModule],
    template: `
    <p-button icon="pi pi-download" [label]="label" [outlined]="true" severity="secondary"
      (onClick)="menu.toggle($event)" size="small" />
    <p-menu #menu [model]="menuItems" [popup]="true" />
  `
})
export class ExportButtonComponent {
  @Input() module = '';
  @Input() label = 'Export';
  @Input() data: Record<string, unknown>[] = [];

  menuItems: MenuItem[] = [];
  private http = inject(HttpClient);
  private toast = inject(ToastService);

  ngOnInit() {
    this.menuItems = [
      { label: 'PDF', icon: 'pi pi-file-pdf', command: () => this.exportAs('pdf') },
      { label: 'Excel', icon: 'pi pi-file-excel', command: () => this.exportAs('excel') },
      { label: 'CSV', icon: 'pi pi-file', command: () => this.exportAs('csv') },
    ];
  }

  exportAs(format: string) {
    if (format === 'csv' && this.data.length > 0) {
      this.downloadCSV();
      return;
    }
    const url = `/api/reports/generate/${this.module}/${format}`;
    this.http.get(url, { responseType: 'blob' }).subscribe({
      next: (blob) => {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = `${this.module}-export.${format === 'excel' ? 'xlsx' : format}`;
        a.click();
        URL.revokeObjectURL(a.href);
      },
      error: () => {
        if (this.data.length > 0) {
          this.downloadCSV();
          this.toast.warn('Server export unavailable — downloaded as CSV instead.');
        } else {
          this.toast.error('Export failed. Please try again.');
        }
      },
    });
  }

  private downloadCSV() {
    if (!this.data.length) return;
    const keys = Object.keys(this.data[0]);
    const csv = [keys.join(','), ...this.data.map(row => keys.map(k => `"${String(row[k] ?? '').replace(/"/g, '""')}"`).join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `${this.module}-export.csv`;
    a.click();
    URL.revokeObjectURL(a.href);
  }
}

