@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'app-pdf-viewer',
  standalone: true,
  imports: [CommonModule, NgxExtendedPdfViewerModule],
  template: `
    <div class="pdf-container" [style.height]="height">
      <ngx-extended-pdf-viewer
        *ngIf="useExtendedViewer && src"
        [src]="src"
        [height]="height"
        [zoom]="zoomPercent"
        [showToolbar]="showToolbar"
        [showSidebarButton]="showSidebar"
        [showFindButton]="true"
        [showPrintButton]="true"
        [showDownloadButton]="true"
        [showZoomButtons]="true"
        [showPagingButtons]="true"
        [textLayer]="true"
        [language]="language"
        (pageChange)="onPageChange($event)"
      ></ngx-extended-pdf-viewer>
      <iframe
        *ngIf="!useExtendedViewer && src"
        [src]="src"
        class="pdf-frame"
        [title]="title"
      ></iframe>
      <div *ngIf="!src" class="pdf-placeholder">
        <i class="pi pi-file-pdf"></i>
        <span>No PDF loaded</span>
      </div>
    </div>
    <div *ngIf="showToolbar && !useExtendedViewer && src" class="pdf-toolbar">
      <button class="toolbar-btn" (click)="zoomOut()" title="Zoom Out">
        <i class="pi pi-search-minus"></i>
      </button>
      <span class="zoom-level">{{ zoomPercent }}%</span>
      <button class="toolbar-btn" (click)="zoomIn()" title="Zoom In">
        <i class="pi pi-search-plus"></i>
      </button>
      <button class="toolbar-btn" (click)="downloadPdf()" title="Download">
        <i class="pi pi-download"></i>
      </button>
      <button class="toolbar-btn" (click)="printPdf()" title="Print">
        <i class="pi pi-print"></i>
      </button>
    </div>
  `,
  styles: [`
    .pdf-container { width: 100%; border: 1px solid var(--surface-border, #e0e0e0); border-radius: var(--radius); overflow: hidden; position: relative; }
    .pdf-frame { width: 100%; height: 100%; border: none; }
    .pdf-placeholder { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; gap: 8px; color: var(--text-color-secondary); }
    .pdf-placeholder i { font-size: var(--font-size-6xl); }
    .pdf-toolbar { display: flex; align-items: center; gap: 8px; padding: 8px 12px; background: var(--surface-ground, #f9fafb); border-top: 1px solid var(--surface-border); }
    .toolbar-btn { background: none; border: 1px solid var(--surface-border); border-radius: var(--radius-xs); padding: 6px 10px; cursor: pointer; color: var(--text-color); transition: background 0.2s; }
    .toolbar-btn:hover { background: var(--surface-hover); }
    .zoom-level { font-size: var(--font-size-sm); font-weight: 500; min-width: 40px; text-align: center; }
  `],
})
export class PdfViewerComponent implements AfterViewInit, OnChanges {
  @Input() src: string = '';
  @Input() height = '600px';
  @Input() title = 'PDF Document';
  @Input() showToolbar = true;
  @Input() showSidebar = false;
  @Input() useExtendedViewer = false;
  @Input() language = 'en';
  @Output() pageChange = new EventEmitter<number>();

  zoomPercent = 100;
  private zoomStep = 25;

  ngAfterViewInit(): void {}

  ngOnChanges(_changes: SimpleChanges): void {}

  onPageChange(page: number): void {
    this.pageChange.emit(page);
  }

  zoomIn(): void {
    this.zoomPercent = Math.min(this.zoomPercent + this.zoomStep, 300);
  }

  zoomOut(): void {
    this.zoomPercent = Math.max(this.zoomPercent - this.zoomStep, 25);
  }

  downloadPdf(): void {
    if (!this.src) return;
    const a = document.createElement('a');
    a.href = this.src;
    a.download = this.title || 'document.pdf';
    a.click();
  }

  printPdf(): void {
    if (!this.src) return;
    const win = window.open(this.src, '_blank');
    if (win) {
      win.addEventListener('load', () => win.print());
    }
  }
}

/**
 * Serialization utilities for ECharts options objects.
 *
 * Provides `serializeOptions` and `deserializeOptions` to safely convert
 * EChartsOption objects to/from JSON strings, handling function values
 * and circular references gracefully.
 *
 * Requirements: 18.3, 18.4, 18.5
 */
import type { EChartsOption } from 'echarts';

/** Sentinel placeholder used to represent function values in serialized JSON. */
const FUNCTION_PLACEHOLDER = '__function__';

/**
 * Serialize an `EChartsOption` to a JSON string.
 *
 * Function values are replaced with the `"__function__"` placeholder.
 * Circular references are handled gracefully — the offending value is
 * replaced with `"__circular__"`.
 *
 * @param options - The ECharts options object to serialize.
 * @returns A valid JSON string representation.
 */
export function serializeOptions(options: EChartsOption): string {
  const seen = new WeakSet<object>();

  return JSON.stringify(options, (_key, value) => {
    if (typeof value === 'function') {
      return FUNCTION_PLACEHOLDER;
    }

    // Guard against circular references
    if (typeof value === 'object' && value !== null) {
      if (seen.has(value)) {
        return '__circular__';
      }
      seen.add(value);
    }

    return value;
  });
}

/**
 * Deserialize a JSON string back into an `EChartsOption`.
 *
 * `"__function__"` placeholders are restored to no-op functions by default.
 * If a `builderRegistry` is provided, the placeholder's object key is used
 * to look up a real function from the registry.
 *
 * Parse errors are handled gracefully — an empty object is returned.
 *
 * @param json - The JSON string to parse.
 * @param builderRegistry - Optional map of key → function for restoring placeholders.
 * @returns The restored EChartsOption object.
 */
export function deserializeOptions(
  json: string,
  builderRegistry?: Record<string, Function>,
): EChartsOption {
  try {
    const parsed = JSON.parse(json);
    return restoreFunctions(parsed, builderRegistry);
  } catch {
    return {} as EChartsOption;
  }
}

/**
 * Recursively walk an object tree and replace `"__function__"` placeholder
 * strings with callable functions.
 */
function restoreFunctions(
  obj: unknown,
  registry?: Record<string, Function>,
): unknown {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map((item) => restoreFunctions(item, registry));
  }

  const result: Record<string, unknown> = {};
  for (const key of Object.keys(obj)) {
    const value = obj[key];

    if (value === FUNCTION_PLACEHOLDER) {
      result[key] = registry?.[key] ?? (() => {});
    } else if (typeof value === 'object' && value !== null) {
      result[key] = restoreFunctions(value, registry);
    } else {
      result[key] = value;
    }
  }

  return result;
}

